def_ixp = json.load(open('/tmp/def_ixp.json'))['Data']['Node']
def_apiwf = json.load(open('/tmp/def_apiwf.json'))['Data']['Node']
def_sop = json.load(open('/tmp/def_sop.json'))['Data']['Node']
def_ds = json.load(open('/tmp/def_ds_query.json'))['Data']['Node']

# Normalize definition keys: registry get returns nodeType/version fields
# flow_edit.py expects 'nodeType' key in definitions
# Check existing flow for how ds is stored (it uses the def_ds already present)

flow = {
  "id": "8a03a14c-afce-4cec-b44d-162a91b2e1b6",
  "version": "1.9",
  "name": "BillingDisputeResolution",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {"label": "Manual trigger"},
      "inputs": {
        "entryPointId": "b57045ba-62d7-489a-8ae7-12bdfa589b19",
        "isDefaultEntryPoint": True
      }
    },
    # IxP extraction
    {
      "id": "invoiceExtraction",
      "type": "uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178",
      "typeVersion": "1.0.0",
      "display": {"label": "Extract Invoice Fields"},
      "inputs": {
        "model": {
          "id": "99f5bbfa-5f29-8033-8662-25001b6bb18e",
          "modelName": "invoices-billing-f0c606f9-ixp",
          "modelDisplayName": "invoices-billing",
          "folderKey": "79a7d12e-da84-4bf4-ab60-7f34b44dd178",
          "folderName": "Shared/uipath-maestro-flow/BillingDispute",
          "folderPath": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c.5da18ec0-7de1-4e57-aaf1-ddc8a369c199.79a7d12e-da84-4bf4-ab60-7f34b44dd178",
          "description": ""
        },
        "modelName": "invoices-billing-f0c606f9-ixp",
        "description": "",
        "projectName": "invoices-billing-f0c606f9-ixp",
        "versionTag": "",
        "folderKey": "79a7d12e-da84-4bf4-ab60-7f34b44dd178",
        "folderName": "Shared/uipath-maestro-flow/BillingDispute",
        "fileRef": "=js:$vars.start.output.disputedInvoice",
        "pageRange": ""
      },
      "outputs": {
        "output": {
          "name": "output",
          "type": "object",
          "source": "=this",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    # Normalize data script
    {
      "id": "normalizeData",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {"label": "Normalize Invoice Fields"},
      "inputs": {
        "script": """const fields = $vars.invoiceExtraction.output.ExtractionResult?.ResultsDocument?.Fields ?? [];
const normalized = fields.map(f => ({ Id: f.FieldId, Name: f.FieldName, Value: f.Values?.[0]?.Value ?? null, Type: f.DataType }));
return { normalizedFields: normalized };"""
      }
    },
    # CRM Lookup (pre-existing)
    {
      "id": "crmLookup1",
      "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
      "typeVersion": "1.0.0",
      "display": {"label": "CRM Lookup"},
      "inputs": {}
    },
    # ERP Lookup (pre-existing)
    {
      "id": "erpLookup1",
      "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
      "typeVersion": "1.0.0",
      "display": {"label": "ERP Lookup"},
      "inputs": {}
    },
    # Merge parallel lookups
    {
      "id": "mergeLookups",
      "type": "core.logic.merge",
      "typeVersion": "1.0",
      "display": {"label": "Merge Lookups"}
    },
    # Discrepancy detection script
    {
      "id": "discrepancyDetection",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {"label": "Detect Discrepancies"},
      "inputs": {
        "script": """const disputedItems = $vars.start.output.webhookPayload?.invoice?.lineItems ?? [];
const erpRecords = $vars.erpLookup1.output?.value ?? [];
const discrepancies = [];
let totalOvercharge = 0;
let totalUndercharge = 0;
for (const item of disputedItems) {
  const invoiceNum = item.invoiceNumber ?? '';
  const normalized = invoiceNum.startsWith('MCS-') ? invoiceNum.replace(/^MCS-/, '') : invoiceNum;
  const erpRow = erpRecords.find(r => r.InvoiceNumber === normalized || r.InvoiceNumber === invoiceNum);
  if (!erpRow) { discrepancies.push({ invoiceNumber: invoiceNum, issue: 'not_found_in_erp', disputedAmount: item.amount, erpAmount: null, delta: null }); continue; }
  const delta = (item.amount ?? 0) - (erpRow.Amount ?? 0);
  if (Math.abs(delta) > 0.01) {
    discrepancies.push({ invoiceNumber: invoiceNum, issue: delta > 0 ? 'overcharge' : 'undercharge', disputedAmount: item.amount, erpAmount: erpRow.Amount, delta });
    if (delta > 0) totalOvercharge += delta; else totalUndercharge += Math.abs(delta);
  }
}
return { discrepancies, totalOvercharge, totalUndercharge, hasDiscrepancies: discrepancies.length > 0 };"""
      }
    },
    # SOP context resource node
    {
      "id": "sopContextNode",
      "type": "uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
      "typeVersion": "1.0.0",
      "display": {"label": "Billing Dispute SOP Index"},
      "inputs": {
        "indexId": "cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
        "indexName": "Billing Dispute SOP Index",
        "folderKey": "79a7d12e-da84-4bf4-ab60-7f34b44dd178",
        "folderPath": "Shared/uipath-maestro-flow/BillingDispute",
        "retrievalMode": "semantic",
        "query": {
          "mode": "prompt",
          "textValue": "",
          "promptValue": "The query for the Semantic strategy",
          "argumentPath": ""
        },
        "threshold": 0,
        "resultCount": 3,
        "fileExtension": "All",
        "folderPathPrefix": {
          "mode": "text-builder",
          "textValue": "",
          "promptValue": "",
          "argumentPath": ""
        },
        "citations": "enabled",
        "outputColumns": [],
        "webSearchGrounding": {"value": "enabled"},
        "source": True
      }
    },
    # Dispute Analyst agent
    {
      "id": "disputeAnalyst",
      "type": "uipath.agent.autonomous",
      "typeVersion": "1.3",
      "display": {"label": "Dispute Analyst"},
      "inputs": {
        "systemPrompt": "You are a billing dispute analyst.",
        "userPrompt": "Analyze the billing dispute and return a determination.",
        "source": "774a31b9-a777-4905-8f27-3d936f54ac45",
        "agentInputVariables": [
          {"id": "normalizeData__output__normalizedFields", "type": "array", "binding": "=$vars.normalizeData.output.normalizedFields", "description": "Normalized invoice fields from IxP extraction"},
          {"id": "discrepancyDetection__output__discrepancies", "type": "array", "binding": "=$vars.discrepancyDetection.output.discrepancies", "description": "Detected discrepancies"},
          {"id": "discrepancyDetection__output__totalOvercharge", "type": "number", "binding": "=$vars.discrepancyDetection.output.totalOvercharge", "description": "Total overcharge amount"},
          {"id": "discrepancyDetection__output__totalUndercharge", "type": "number", "binding": "=$vars.discrepancyDetection.output.totalUndercharge", "description": "Total undercharge amount"},
          {"id": "crmLookup1__output__value", "type": "object", "binding": "=$vars.crmLookup1.output", "description": "CRM account data"},
          {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload", "description": "Original webhook payload with invoice details"}
        ],
        "agentOutputVariables": [
          {"id": "determination", "type": "string"},
          {"id": "recommendedAction", "type": "string"},
          {"id": "autoResolutionEligible", "type": "boolean"},
          {"id": "creditAmount", "type": "number"},
          {"id": "confidence", "type": "string"},
